"""Content of GRAVITY_SYMBOLS (Markdown + LaTeX): every symbol used for gravity on the 7+1 spacetime, the Einstein and
Lovelock tensors, the generalized frame matrices, the canonical spin connection, the covariant Dirac equation of
dirac16complex and the three epochs (sections 11-14 of 7+1.nb), with its defining equation and its name in the notebook.
Self-contained: every equation needed to define a symbol is written in this document."""
from docgen import Doc
from doc_common import signature_block

W4 = [0.14, 0.24, 0.35, 0.27]
HEAD4 = ['symbol', 'Mathematica', 'definition', 'meaning']


def build(D, today):
    d = Doc('Gravity on the 7+1 spacetime: symbols and their definitions',
            'A dictionary of every symbol used for the curvature, the Einstein and Lovelock tensors, the generalized frame matrices, '
            'the canonical spin connection, the covariant Dirac equation of dirac16complex and the three cosmological epochs — '
            'sections 11–14 of the notebook 7+1.nb',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1)',
             'Document generated by tools/make_docs.py on ' + today],
            'For each symbol this dictionary gives the mathematical notation, the name used in the Mathematica notebook 7+1.nb '
            '(where there is one), the defining equation and its meaning. The symbols are grouped by topic in the order in which '
            'they are introduced; longer defining equations follow each table as displayed formulas. The last sections list '
            'symbols that look alike and the Mathematica names defined in sections 11–14 of 7+1.nb. Every equation needed to '
            'define a symbol is written in this document.')

    # ------------------------------------------------------------------------------------------------
    d.h1('1. Conventions')
    d.ul(['Units: $\\hbar=c=1$. A prime is $d/dx_0$ for functions of the time $x_0$ (and $d/dr$ for the functions $f(r)$, $h(r)$ of the static radial metric (2.4)).',
          'Index ranges: Greek $\\mu,\\nu,\\lambda,\\rho,\\sigma,\\alpha,\\beta,\\gamma,\\delta\\in\\lbrace0,\\dots,7\\rbrace$ are coordinate indices; '
          'Latin capitals $A,B,C,D\\in\\lbrace0,\\dots,7\\rbrace$ are frame indices; $i,j\\in\\lbrace1,2,3\\rbrace$ label ordinary space and '
          '$k,l\\in\\lbrace4,\\dots,7\\rbrace$ the auxiliary space (for the static radial metric (2.4), $k\\in\\lbrace2,\\dots,7\\rbrace$). Repeated indices are summed.',
          'The abstract indices of the xAct computation (section 4.3) are the letters $a$, $b$, $c$, $d$, $f$, $i$, $j$, $k$, $l$, $m$, $n$, $p$, $q$, $r$, $s$, $y$; they are '
          'unrelated to the index ranges above.',
          'Frame indices are raised and lowered with $\\eta$, coordinate indices with $g_{\\mu\\nu}$.',
          'Signature: one time-like dimension ($x_0$, $g_{00}>0$) and seven space-like dimensions ($x_1,\\dots,x_7$, negative squares). '
          'The xAct declaration $\\{7,1,0\\}$ counts them (seven space-like, one time-like, none degenerate), as in the reference notebook; '
          'the matrix $\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$ is a different object, simply the squares of the octonion basis '
          '($e_0^2=+1$, $e_i^2=-1$, $\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$).',
          'Matrices: $1_n$ is the $n\\times n$ identity, $M^{\\mathsf T}$ the transpose, $[X,Y]=XY-YX$, $\\lbrace X,Y\\rbrace=XY+YX$.',
          'Mathematica lists are 1-based: $g_{\\mu\\nu}$ is `g[[μ+1, ν+1]]`, $\\Gamma_A$ is `Γ17[A]` (an argument, not a list index). '
          'Greek letters in names are named characters: `\\[CapitalGamma]` is Γ, `\\[Eta]` is η, `\\[Alpha]` is α, `\\[Beta]` is β, '
          '`\\[Delta]` is δ, `\\[CapitalLambda]` is Λ.',
          'Christoffel symbols are written $\\{{}^{\\lambda}_{\\mu\\nu}\\}$, never $\\Gamma$: in this project $\\Gamma$ always denotes a Dirac matrix.'])
    signature_block(d, eta=r'\eta', eta71=r'\eta_{71}', gam=r'\Gamma')

    # ------------------------------------------------------------------------------------------------
    d.h1('2. Spacetime, metrics and coordinates')
    d.table(HEAD4, [
        ['$X$; $x_0,\\dots,x_7$', '`X = {x0, …, x7}`', '$X=(x_0,x_1,\\dots,x_7)$', '$x_0$ time (the octonion unit direction), $x_1,x_2,x_3$ '
         'ordinary space, $x_4,\\dots,x_7$ auxiliary space'],
        ['$\\eta_{AB}$', '`η17`', '$\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$, $\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$', 'frame metric: simply the squares of the octonion basis, $e_0^2=+1$ (time), $e_i^2=-1$ (space)'],
        ['$\\eta_{71}$', '`η71`', '$-\\eta=\\mathrm{diag}(-1,+1,\\dots,+1)$', 'the same spacetime in the sign convention of 4+4.nb (space-like $=+1$): seven entries $+1$ (space-like), one $-1$ (time-like), as the xAct list $\\{7,1,0\\}$ counts them'],
        ['$e_A$; $xy$; $\\mathrm{Re}(x)$', '`ev[A]`; `oMul[x, y]`; `oRe[x]`', 'octonion basis units $e_0=1,e_1,\\dots,e_7$, octonion product, real part (section 3 of 7+1.nb)', 'used in section 12.2 to check $\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$ and $\\mathrm{Re}(xx)=x\\cdot\\eta\\cdot x$'],
        ['$g_{\\mu\\nu}$, $g^{\\mu\\nu}$', '`cv["g"]`, `cv["ginv"]`', '$g^{\\mu\\lambda}g_{\\lambda\\nu}=\\delta^\\mu_\\nu$', 'metric and inverse metric'],
        ['$|g|$', '—', '$|\\det g_{\\mu\\nu}|$', 'volume factor $\\sqrt{|g|}$'],
        ['$a$, $b$', '`a3[x0]`, `b4[x0]`', 'cosmological metric (2.1)', 'scale factors of ordinary and auxiliary space'],
        ['$H_a$, $H_b$', '`Ha`, `Hb`', '$H_a=a\'/a$, $H_b=b\'/b$', 'Hubble rates'],
        ['$H_a\'$, $H_b\'$', '`dHa`, `dHb`', 'derivatives of the Hubble rates', '`toH` rewrites $a\'$, $a\'\'$, $b\'$, $b\'\'$ with them'],
        ['$N$', '`nL[x0]`', '$g_{00}=N^2$', 'lapse function (variational check)'],
        ['$n,a,b$ (inhomogeneous)', '`nP`, `aP`, `bP`', 'polynomials (2.2)', 'inhomogeneous test metric'],
        ['$F$', '`fPP`', 'arbitrary function of $(x_0-x_1,x_2,x_3)$', 'profile of the plane wave (2.3)'],
        ['$l_\\mu$', '`lNull`', '$l_\\mu=(1,-1,0,\\dots,0)$, $\\eta^{\\mu\\nu}l_\\mu l_\\nu=0$', 'null vector of the plane wave'],
        ['$r$; $f$, $h$', '`x1`; `fR[x1]`, `hR[x1]`', 'static radial metric (2.4)', 'radial coordinate and two arbitrary positive functions'],
        ['$C$', '`cConf[x0]`', '$g=C(x_0)^2\\eta$', 'conformal factor'],
        ['$H$, $q_H$', '`H`, `qH`', '$a=e^{Hx_0}$, $b=e^{q_HHx_0}$', 'constant Hubble rate and ratio of the exponential vacuum solutions (4.9); $H$ is also the inverse length of the field equations (4.7)'],
    ], widths=W4)
    d.p('**(2.1) Cosmological metric:**')
    d.eq(r'ds^2=dx_0^2-a(x_0)^2\big(dx_1^2+dx_2^2+dx_3^2\big)-b(x_0)^2\big(dx_4^2+dx_5^2+dx_6^2+dx_7^2\big).')
    d.p('**(2.2) Inhomogeneous metric** (checked exactly at the point $x_0=1/2$, $x_4=1/3$, code `ptP`):')
    d.eq(r'ds^2=n^2dx_0^2-a^2\sum_{i=1}^3dx_i^2-b^2\sum_{k=4}^7dx_k^2,\quad n=1+\tfrac{x_0x_4}{5}+\tfrac{x_0^2}{11},\ \ '
         r'a=1+\tfrac{x_0}{3}+\tfrac{x_4^2}{7},\ \ b=2-\tfrac{x_0x_4}{4}+\tfrac{x_0^2}{9}+\tfrac{x_4}{13}.')
    d.p('**(2.3) Plane gravitational wave (pp-wave):**')
    d.eq(r'ds^2=dx_0^2-dx_1^2-\cdots-dx_7^2+F(x_0-x_1,x_2,x_3)\,(dx_0-dx_1)^2 .')
    d.p('**(2.4) Static metric with a radial coordinate** $r=x_1>0$:')
    d.eq(r'ds^2=f(r)\,dx_0^2-h(r)\,dr^2-r^2\big(dx_2^2+\cdots+dx_7^2\big).')

    # ------------------------------------------------------------------------------------------------
    d.h1('3. Curvature')
    d.table(HEAD4, [
        ['$\\{{}^{\\lambda}_{\\mu\\nu}\\}$', '`cv["chr"]`', '(3.1)', 'Christoffel symbols; `chr[[λ+1, μ+1, ν+1]]`'],
        ['$R^\\rho{}_{\\sigma\\mu\\nu}$', '`cv["riem"]`', '(3.2)', 'Riemann tensor (Landau–Lifshitz convention)'],
        ['$R_{\\rho\\sigma\\mu\\nu}$', '`riemLow[cv]`', '$g_{\\rho\\lambda}R^\\lambda{}_{\\sigma\\mu\\nu}$', 'Riemann tensor, all indices down'],
        ['$R^{\\gamma\\delta}{}_{\\alpha\\beta}$', '`cv["rud"]`, `rudAssoc`', '$g^{\\delta\\sigma}R^\\gamma{}_{\\sigma\\alpha\\beta}$', 'two indices up, two down; `rudAssoc` lists the non-zero entries with $\\gamma<\\delta$, $\\alpha<\\beta$'],
        ['$R_{\\sigma\\nu}$', '`cv["ric"]`', '$R^\\rho{}_{\\sigma\\rho\\nu}$', 'Ricci tensor'],
        ['$R$', '`cv["R"]`', '$g^{\\sigma\\nu}R_{\\sigma\\nu}$', 'scalar curvature'],
        ['$G^\\mu{}_\\nu$', '`cv["G"]`', '$R^\\mu{}_\\nu-\\tfrac12\\delta^\\mu_\\nu R$', 'Einstein tensor'],
        ['$K_{AB}$', '`secK[cv, A, B]`', '$R^{AB}{}_{AB}$ (no sum)', 'sectional curvature of the cosmological metric'],
        ['$\\nabla_\\mu T^\\mu{}_\\nu$', '`divergenceMixed`', '(3.3)', 'divergence of a mixed tensor'],
        ['—', '`curvature[g, simp]`', '—', 'the curvature engine: returns all of the above for a metric matrix'],
    ], widths=W4)
    d.align([r'\{{}^{\lambda}_{\mu\nu}\}&=\tfrac12\,g^{\lambda\rho}\big(\partial_\mu g_{\rho\nu}+\partial_\nu g_{\rho\mu}-\partial_\rho g_{\mu\nu}\big),&&(3.1)',
             r'R^{\rho}{}_{\sigma\mu\nu}&=\partial_\mu\{{}^{\rho}_{\sigma\nu}\}-\partial_\nu\{{}^{\rho}_{\sigma\mu}\}+\{{}^{\rho}_{\mu\lambda}\}\{{}^{\lambda}_{\sigma\nu}\}-\{{}^{\rho}_{\nu\lambda}\}\{{}^{\lambda}_{\sigma\mu}\},&&(3.2)',
             r'\nabla_\mu T^\mu{}_\nu&=\partial_\mu T^\mu{}_\nu+\{{}^{\mu}_{\mu\lambda}\}T^\lambda{}_\nu-\{{}^{\lambda}_{\mu\nu}\}T^\mu{}_\lambda .&&(3.3)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('4. Lovelock tensors and field equations')
    d.h2('4.1 Generalized Kronecker delta and Lovelock tensors')
    d.table(HEAD4, [
        ['$\\delta^{\\mu_1\\cdots\\mu_n}_{\\nu_1\\cdots\\nu_n}$', '`gKD[up, dn]`', '(4.1)', 'generalized Kronecker delta (explicit index values)'],
        ['$\\delta^{\\text{upper}}_{\\text{lower}}$', '`kδ[lower, upper]`', '(4.1) with xAct `delta`', 'the same with abstract indices (xAct)'],
        ['$E^{(k)\\mu}{}_\\nu$', '`lovelockE[ra, k]`; `Lovelock1/2/3`', '(4.2)', 'Lovelock tensor of order $k$; `Lovelock`$k$ $=E^{(k)b}{}_a$'],
        ['$L_k$', '`lovelockL[ra, k]`', '(4.3)', 'Lovelock density of order $k$'],
        ['$E^{(0)}$', '`lovelockE[ra, 0]`', '$-\\tfrac12\\delta^\\mu_\\nu$', 'cosmological term'],
        ['$L_2$', '`lanczosDiag[cv][[1]]`', '$R^2-4R_{\\mu\\nu}R^{\\mu\\nu}+R_{\\mu\\nu\\rho\\sigma}R^{\\mu\\nu\\rho\\sigma}$', 'Gauss–Bonnet density'],
        ['$H_{\\mu\\nu}$', '`lanczosDiag[cv][[2]]`', '(4.4)', 'Lanczos tensor ($=E^{(2)}$)'],
        ['$\\mathcal U$, $\\mathcal V$', '`pairSets`, `orderedSeqs`', 'sets of $k$ disjoint pairs; ordered sequences of pairs', 'index pairs of the pair-set algorithm (4.5)'],
        ['sgn', '`Signature[up] Signature[dn]`', 'sign of the permutation upper → lower', ''],
        ['$E^{(k)}$ (cosmological)', '`ECos[[k+1]]`, `LCos[[k+1]]`', 'closed forms in $H_a,H_b,H_a\',H_b\'$', 'Lovelock tensors and densities of (2.1)'],
    ], widths=W4)
    d.align([r'\delta^{\mu_1\cdots\mu_n}_{\nu_1\cdots\nu_n}&=\det\big[\delta^{\mu_i}_{\nu_j}\big]_{i,j=1}^{n},&&(4.1)',
             r'E^{(k)\mu}{}_{\nu}&=-\frac{1}{2^{k+1}}\,\delta^{\mu\alpha_1\beta_1\cdots\alpha_k\beta_k}_{\nu\gamma_1\delta_1\cdots\gamma_k\delta_k}\,R^{\gamma_1\delta_1}{}_{\alpha_1\beta_1}\cdots R^{\gamma_k\delta_k}{}_{\alpha_k\beta_k},&&(4.2)',
             r'L_k&=\frac{1}{2^{k}}\,\delta^{\alpha_1\beta_1\cdots\alpha_k\beta_k}_{\gamma_1\delta_1\cdots\gamma_k\delta_k}\,R^{\gamma_1\delta_1}{}_{\alpha_1\beta_1}\cdots R^{\gamma_k\delta_k}{}_{\alpha_k\beta_k},&&(4.3)',
             r'H_{\mu\nu}&=2\big(RR_{\mu\nu}-2R_{\mu\alpha}R^\alpha{}_\nu-2R^{\alpha\beta}R_{\mu\alpha\nu\beta}+R_\mu{}^{\alpha\beta\gamma}R_{\nu\alpha\beta\gamma}\big)-\tfrac12g_{\mu\nu}L_2,&&(4.4)',
             r'E^{(k)\mu}{}_\nu&=-2^{k-1}k!\sum_{\mathcal U}\sum_{\mathcal V}\mathrm{sgn}(\mu\,\mathcal U\to\nu\,\mathcal V)\prod_{i=1}^kR^{\mathcal V_i}{}_{\mathcal U_i}.&&(4.5)'])
    d.h2('4.2 The xAct objects (the method of the reference notebook Einstein-Lovelock-7+1-Nash.nb)')
    d.table(HEAD4, [
        ['$M_8$', '`M8`', '`DefManifold[M8, 8, {a, b, c, d, f, i, j, k, l, m, n, p, q, r, s, y}]`', 'the 8-dimensional manifold with its abstract indices'],
        ['$g$', '`g71`', '`DefMetric[{7, 1, 0}, g71[-a, -b], CD, …]`', 'abstract metric; $\\{7,1,0\\}$: seven space-like dimensions, one time-like, none degenerate (the declaration of the reference notebook)'],
        ['$\\nabla$', '`CD`', 'Levi-Civita derivative of `g71`', 'after `CD = LC[g71]`: the connection of a component metric'],
        ['chart', '`chartM8`', '`DefChart[chartM8, M8, {0, …, 7}, {x0[], …, x7[]}, …]`', 'coordinate chart; `x0[]` … `x7[]` coordinate scalars'],
        ['$\\delta_a{}^b$', '`delta[-a, b]`', 'Kronecker delta of xAct', ''],
        ['$R_{ab}{}^{cd}$ etc.', '`RiemannCD`, `RicciCD`, `RicciScalarCD`, `EinsteinCD`', 'curvature of `CD` (abstract, or components after the assignments)', ''],
        ['—', '`MyArrayComponents`', '`MyArrayComponents[expr] := expr // ToBasis[chartM8] // ComponentArray // ToValues // ToValues // Simplify`', 'component array of an expression'],
        ['—', '`toXc`, `fromXc`', '$x_\\mu\\to$ `xμ[]` and back', 'between this notebook’s coordinates and the chart scalars'],
        ['—', '`xActLovelock[gm]`', '`g71 = CTensor[gm, {-chartM8, -chartM8}]`; `MetricCompute`; `CD = LC[g71]`; `RiemannCD = Riemann[CD]`, …; `MyArrayComponents` of `Lovelock1/2/3`, `EinsteinCD[-a, b]`, transposed', 'returns $E^{(1)},E^{(2)},E^{(3)},G$ as matrices (row $\\mu$, column $\\nu$)'],
        ['—', '`xlCos`, `xlPP`, `xlExp`', '`xActLovelock` of (2.1), (2.3) and of $a=e^{Hx_0}$, $b=e^{q_HHx_0}$', ''],
    ], widths=[0.13, 0.22, 0.40, 0.25])
    d.h2('4.3 Couplings and field equations')
    d.table(HEAD4, [
        ['$\\kappa$, $G_8$', '`kap`', '$\\kappa=8\\pi G_8$', 'gravitational coupling; Newton constant in 8 dimensions'],
        ['$\\alpha_k$', '`alf[k]`', '(4.6)', 'Lovelock couplings, $\\alpha_1=1$, $\\alpha_2$ (length²), $\\alpha_3$ (length⁴)'],
        ['$\\bar\\Lambda$', '`lamb`', '$\\alpha_0=2\\bar\\Lambda$', 'cosmological constant (length$^{-2}$); in the field equations of the three epochs (section 7) it is written $\\Lambda$'],
        ['$w_1,w_2,w_3$', '`w1`, `w2`, `w3`', '(4.7)', 'pure-number couplings of the reference notebook'],
        ['$\\Lambda$', '`\\[CapitalLambda]`', '(4.7)', 'pure-number cosmological constant of the reference notebook'],
        ['$H$', '`H`', '(4.7)', 'fundamental inverse length'],
        ['$T^\\mu{}_\\nu$', '—', '$\\delta S_{\\rm matter}=\\tfrac12\\int\\sqrt{|g|}T_{\\mu\\nu}\\delta g^{\\mu\\nu}$', 'energy–momentum tensor'],
        ['$\\varepsilon$, $p_a$, $p_b$', '—', '$T=\\mathrm{diag}(\\varepsilon,-p_a,-p_a,-p_a,-p_b,\\dots,-p_b)$', 'energy density and pressures'],
    ], widths=W4)
    d.align([r'S&=-\frac{1}{2\kappa}\int d^8X\sqrt{|g|}\sum_{k=0}^3\alpha_kL_k+S_{\rm matter},\qquad \sum_{k=0}^{3}\alpha_kE^{(k)\mu}{}_\nu=\kappa T^\mu{}_\nu,&&(4.6)',
             r'0&=-\Lambda\,\delta^\mu_\nu+H^{-2}w_1\,E^{(1)\mu}{}_\nu+H^{-4}w_2\,E^{(2)\mu}{}_\nu+H^{-6}w_3\,E^{(3)\mu}{}_\nu,&&(4.7)',
             r'\alpha_2&=\frac{w_2}{w_1H^2},\quad \alpha_3=\frac{w_3}{w_1H^4},\quad \bar\Lambda=\frac{\Lambda H^2}{w_1}\quad(T=0),&&(4.8)',
             r"a&=e^{Hx_0},\quad b=e^{q_HHx_0}:\quad H_a=H,\ H_b=q_HH,\ H_a'=H_b'=0;&&(4.9)",
             r"&\qquad q_H=-1:\ \ w_2=\tfrac{\Lambda}{4}-\tfrac{w_1}{2},\ \ w_3=\tfrac{w_1}{24}-\tfrac{\Lambda}{36}."])

    # ------------------------------------------------------------------------------------------------
    d.h1('5. Frames, spin connection, spinor curvature')
    d.table(HEAD4, [
        ['$e^A{}_\\mu$', '`fd["e"]`', '$g_{\\mu\\nu}=\\eta_{AB}e^A{}_\\mu e^B{}_\\nu$', 'frame field (vielbein); `e[[A+1, μ+1]]`'],
        ['$e_A{}^\\mu$', '`fd["ei"]`', '$e_A{}^\\mu e^A{}_\\nu=\\delta^\\mu_\\nu$', 'inverse frame; `ei[[μ+1, A+1]]`'],
        ['$\\Gamma_A$', '`Γ17[A]`', '$\\Gamma_0=\\left(\\begin{smallmatrix}0&1_8\\\\1_8&0\\end{smallmatrix}\\right)$, $\\Gamma_i=\\left(\\begin{smallmatrix}\\tau^O_i&0\\\\0&-\\tau^O_i\\end{smallmatrix}\\right)$', 'real 16×16 Dirac matrices, $\\lbrace\\Gamma_A,\\Gamma_B\\rbrace=2\\eta_{AB}1_{16}$'],
        ['$\\Gamma^A$', '`Γ17up[A]`', '$\\eta^{AA}\\Gamma_A$ (no sum)', ''],
        ['$\\Gamma_\\mu(X)$', '`fd["Gam"]`', '$e^A{}_\\mu\\Gamma_A$', 'generalized frame matrices'],
        ['$\\Gamma^\\mu(X)$', '`fd["GamUp"]`', '$e_A{}^\\mu\\Gamma^A$', ''],
        ['$\\omega_\\mu{}^A{}_B$', '`fd["om"]`', '(5.1)', 'canonical spin connection'],
        ['$\\omega_{\\mu AB}$', '`fd["omL"]`', '$\\eta_{AC}\\omega_\\mu{}^C{}_B$', 'antisymmetric in $A,B$'],
        ['$\\Omega_\\mu$', '`fd["Om"]`', '$\\tfrac14\\omega_{\\mu AB}\\Gamma^A\\Gamma^B$', 'spinor connection (real 16×16)'],
        ['$\\mathcal F_{\\mu\\nu}$', '`fd["F"]`', '(5.2)', 'spinor curvature'],
        ['$R_{AB\\mu\\nu}$', '`rABmn`', '$\\eta_{AC}e^C{}_\\rho R^\\rho{}_{\\sigma\\mu\\nu}e_B{}^\\sigma$', 'Riemann tensor with two frame indices'],
        ['$C^A{}_{BC}$', '`structureC`', '(5.3)', 'structure coefficients of the frame'],
        ['$\\omega_{C,AB}$', '`omegaFrame`', '$e_C{}^\\mu\\omega_{\\mu AB}$', 'spin connection with a frame form index'],
        ['$1_{16}$, $0_{16}$', '`ID16`, `Zero16`', '', 'identity and zero 16×16 matrices'],
        ['—', '`frameData`, `frameChecks`, `cartanEq`, `structureFormula`', '', 'compute and check the frame data of a metric'],
    ], widths=W4)
    d.align([r'\omega_\mu{}^A{}_B&=e^A{}_\nu\big(\partial_\mu e_B{}^\nu+\{{}^{\nu}_{\mu\lambda}\}e_B{}^\lambda\big),&&(5.1)',
             r'\mathcal F_{\mu\nu}&=\partial_\mu\Omega_\nu-\partial_\nu\Omega_\mu+[\Omega_\mu,\Omega_\nu]=\tfrac14R_{AB\mu\nu}\Gamma^A\Gamma^B,&&(5.2)',
             r'C^A{}_{BC}&=e_B{}^\mu e_C{}^\nu\big(\partial_\mu e^A{}_\nu-\partial_\nu e^A{}_\mu\big),\qquad \omega_{C,AB}=-\tfrac12\big(C_{ACB}+C_{BAC}-C_{CBA}\big).&&(5.3)'])
    d.p('The total covariant derivative and the vielbein postulate:')
    d.eq(r'\nabla_\mu\Gamma_\nu=\partial_\mu\Gamma_\nu-\{{}^{\lambda}_{\mu\nu}\}\Gamma_\lambda+[\Omega_\mu,\Gamma_\nu]=0,\qquad '
         r'\partial_\mu e^A{}_\nu-\{{}^{\lambda}_{\mu\nu}\}e^A{}_\lambda+\omega_\mu{}^A{}_Be^B{}_\nu=0 .')

    # ------------------------------------------------------------------------------------------------
    d.h1('6. The covariant Dirac equation of dirac16complex')
    d.table(HEAD4, [
        ['$\\psi$', '`psiF`', '16 functions of $(x_0,x_1,x_5)$ in the checks', 'the field dirac16complex'],
        ['$\\bar\\psi$', '`psibF`', '$\\psi^\\dagger\\Gamma_0$ (independent functions in the checks)', 'Dirac adjoint'],
        ['$D_\\mu$', '`DpsiCos`, `DpsibCos`', '(6.1)', 'spinor covariant derivative'],
        ['$m$', '`mD`', '', 'mass of dirac16complex'],
        ['$J^\\mu$', '—', '$\\bar\\psi\\Gamma^\\mu\\psi$', 'conserved current'],
        ['$\\chi$', '`chiF`', '$\\chi=(a^3b^4)^{1/2}\\psi$', 'rescaled field (cosmological metric)'],
        ['$c(x_0)$', '`cModes`', '$\\chi=e^{i(\\vec p\\cdot\\vec x+\\vec q\\cdot\\vec y)}c(x_0)$', 'mode function (16 components)'],
        ['$\\vec p$, $\\vec q$', '`pmom[i]`, `qmom[k]`', '$\\vec p=(p_1,p_2,p_3)$, $\\vec q=(q_4,\\dots,q_7)$', 'comoving momenta along ordinary and auxiliary space'],
        ['$\\alpha_j$, $\\beta$', '`αD[j]`, `βD`', '$\\alpha_j=\\Gamma^0\\Gamma^j$, $\\beta=\\Gamma_0$', 'Hamiltonian Dirac matrices'],
        ['$h(x_0)$', '`hCos`', '(6.2)', 'mode Hamiltonian'],
        ['$A_\\mu$, $q$, $\\alpha$', '`aGauge[m]`, `qG`, `alGauge`', '(6.3)', 'abelian gauge field, charge, gauge function'],
        ['$\\chi$ (radial)', '`chiR`', '$\\psi=f^{-1/4}r^{-3}\\chi$', 'rescaled field (static radial metric)'],
    ], widths=W4)
    d.align([r'D_\mu\psi&=\partial_\mu\psi+\Omega_\mu\psi,\qquad D_\mu\bar\psi=\partial_\mu\bar\psi-\bar\psi\,\Omega_\mu,\qquad (i\Gamma^\mu D_\mu-m)\psi=0,&&(6.1)',
             r'h(x_0)&=\sum_{i=1}^{3}\alpha_i\frac{p_i}{a}+\sum_{k=4}^{7}\alpha_k\frac{q_k}{b}+\beta m,\qquad i\frac{dc}{dx_0}=h\,c,&&(6.2)',
             r'D_\mu\psi&=\partial_\mu\psi+\Omega_\mu\psi-iqA_\mu\psi,\qquad \psi\to e^{iq\alpha}\psi,\ \ A_\mu\to A_\mu+\partial_\mu\alpha .&&(6.3)'])

    # ------------------------------------------------------------------------------------------------
    d.h1('7. The three epochs')
    d.table(HEAD4, [
        ['$p$, $q$', '`pK`, `qK`', '$a=x_0^p$, $b=x_0^q$', 'Kasner exponents'],
        ['$p_E$, $q_E$', '`pKE`, `qKE`', '$p=(1+2\\sqrt2)/7$, $q=(2-3\\sqrt2)/14$', 'Einstein–Kasner branch (expanding ordinary space, contracting auxiliary space)'],
        ['$K$, $\\lambda$', '—', '$K=|\\vec p|\\lambda^{1-p}$, $\\lambda=(|\\vec q|/|\\vec p|)^{1/(q-p)}$', 'scaling variable of massless Kasner modes'],
        ['$\\mathcal A$, $\\mathcal B$, $\\mathcal Z$', '`Aop`, `Bop2`, `Zc`', '$\\mathcal A=\\vec n_a\\cdot\\vec\\alpha$, $\\mathcal B=\\vec n_b\\cdot\\vec\\alpha$, $\\mathcal Z=\\mathcal A\\mathcal B\\beta$', '$\\mathcal Z^2=-1_{16}$: conserved $\\pm i$'],
        ['$\\sigma_{1,2,3}$', '`pauli`', 'Pauli matrices', '2×2 reduction of the mode equation'],
        ['$|\\alpha|^2$, $|\\beta|^2$', '`bogoliubov[h, t0, t1, n]`', 'returns $\\lbrace|\\beta|^2,|\\alpha|^2\\rbrace$', 'Bogoliubov coefficients: pair-creation probability'],
        ['$b_0$, $V_\\perp$, $V_c$', '—', '$V_\\perp=b_0^4V_c$', 'static auxiliary scale, its proper and coordinate volume'],
        ['$G_4$', '—', '$G_4=G_8/V_\\perp$', 'four-dimensional Newton constant'],
        ['$M$', '—', '$\\sqrt{m^2+|\\vec q|^2/b_0^2}$', 'Kaluza–Klein mass'],
        ['$H$ (de Sitter)', '`hdS`', '$a=e^{Hx_0}$', 'de Sitter expansion rate'],
        ['$T_{\\rm GH}$', '—', '$H/(2\\pi)$', 'Gibbons–Hawking temperature'],
    ], widths=W4)
    d.eq(r'|\beta|^2=\frac{1}{e^{2\pi M/H}+1}\quad\text{(de Sitter)},\qquad |\beta|^2=e^{-\pi\kappa_{\rm LZ}^2}\quad\text{(Landau–Zener benchmark, } i\dot c=(\kappa_{\rm LZ}\sigma_1+t\sigma_3)c\text{)}.')

    # ------------------------------------------------------------------------------------------------
    d.h1('8. Symbols that look alike')
    d.table(['symbol', 'not to be confused with'], [
        ['$\\Gamma_A$, $\\Gamma_\\mu$ (Dirac matrices)', '$\\{{}^{\\lambda}_{\\mu\\nu}\\}$ (Christoffel symbols; never written $\\Gamma$ here)'],
        ['$H$ (inverse length of (4.7); de Sitter rate)', '$H_a$, $H_b$ (Hubble rates), $H_{\\mu\\nu}$ (Lanczos tensor)'],
        ['$\\Lambda$ (pure number, (4.7))', '$\\bar\\Lambda$ (cosmological constant with dimension length$^{-2}$)'],
        ['$\\alpha_k$ (Lovelock couplings)', '$\\alpha_j$ (Dirac matrices $\\Gamma^0\\Gamma^j$), $\\alpha$ (gauge function), $|\\alpha|^2$ (Bogoliubov)'],
        ['$\\beta$ (Dirac matrix $\\Gamma_0$)', '$|\\beta|^2$ (Bogoliubov coefficient)'],
        ['$q$ (charge; Kasner exponent of $b$; xAct index)', '$q_H$ (ratio of Hubble rates, code `qH`), $\\vec q$ (auxiliary momentum)'],
        ['$w_1,w_2,w_3$ (Lovelock couplings)', '$W^1,W^2,W^3$ (electroweak gauge fields, code `wW1`, `wW2`, `wW3`, in sections 17–19 of 7+1.nb)'],
        ['$K$ (Kasner scaling variable)', '$K_{AB}$ (sectional curvature)'],
        ['$\\kappa=8\\pi G_8$', '$\\kappa_{\\rm LZ}$ (Landau–Zener coupling)'],
        ['`Lovelock1` $=E^{(1)b}{}_a$ (xAct)', '`lovelockE[ra, 1]` $=E^{(1)\\mu}{}_\\nu$ (pair-set sum): the same tensor, row/column order transposed by `xActLovelock`'],
        ['$\\{7,1,0\\}$ (xAct signature: seven space-like dimensions, one time-like)', '$\\eta=\\mathrm{diag}(+1,-1,\\dots,-1)$ (simply the squares of the octonion basis, $\\eta_{AB}=\\mathrm{Re}(e_Ae_B)$)'],
    ], widths=[0.42, 0.58])
    return d
